contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0));
        require(amount > 0);

        c.approve(address(this), amount);
        uint256 beforeAllowance = c.allowance(address(this), address(this));

        bool reverted;
        // top-level state-changing call must be a plain statement; use try-free pattern:
        bytes memory ret;
        (bool ok, bytes memory data) = address(c).call(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", address(this), recipient, amount)
        );
        ret = data;
        reverted = !ok;

        uint256 afterAllowance = c.allowance(address(this), address(this));

        assert(
            beforeAllowance == amount
            && (reverted ? afterAllowance == amount : afterAllowance == 0)
        );
    }

    receive() external payable {}
}

