contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public payable {
        require(to != address(0));
        require(to != address(this));
        require(amount > 0);

        // configure: any positive amount qualifies for the reward
        c.setMinTxnAmount(1);
        // fund the contract without triggering rewards
        c.setRewardRate(0);
        uint256 fund = c.balanceOf(address(this));
        require(fund > 0);
        c.transfer(address(c), fund);
        // enable the reward rate
        c.setRewardRate(5);

        require(amount <= fund);

        uint256 reward = (amount * 5) / 10000;
        uint256 toBalBefore = c.balanceOf(to);
        uint256 contractBalBefore = c.balanceOf(address(c));
        uint256 txRewardBefore = c.txReward(to);

        c.transfer(to, amount);

        assert(
            c.balanceOf(to) == toBalBefore + amount + reward &&
            c.balanceOf(address(c)) == contractBalBefore - reward &&
            c.txReward(to) == txRewardBefore + reward
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 a, uint256 b, uint256 tooMuch) public {
        require(spender != address(0), "zero spender");
        require(tooMuch > a + b, "tooMuch must exceed allowance");

        c.approve(spender, a);
        c.increaseAllowance(spender, b);
        uint256 afterIncrease = c.allowance(address(this), spender);

        bool reverted;
        c.decreaseAllowance(spender, 0);
        // attempt an over-decrease
        assembly { reverted := 1 }
        // top-level try-free revert check via low-level is not allowed to nest; use try statement allowed pattern:
        bool overDecreaseReverted;
        // perform the call at top level, catching revert
        // (state-changing call must be top-level, so do it and catch)
        bytes4 sel = c.decreaseAllowance.selector;
        // Use try/catch on external call
        try c.decreaseAllowance(spender, tooMuch) {
            overDecreaseReverted = false;
        } catch {
            overDecreaseReverted = true;
        }

        assert(
            afterIncrease == a + b &&
            overDecreaseReverted &&
            c.allowance(address(this), spender) == afterIncrease &&
            sel == bytes4(keccak256("decreaseAllowance(address,uint256)"))
        );
    }
    receive() external payable {}
}

