contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 addedValue, uint256 subtractedValue) public {
        require(spender != address(0), "zero spender");

        c.increaseAllowance(spender, addedValue);
        uint256 allowAfterIncrease = c.allowance(address(this), spender);

        bool decReverted;
        if (subtractedValue > allowAfterIncrease) {
            try c.decreaseAllowance(spender, subtractedValue) {
                decReverted = false;
            } catch {
                decReverted = true;
            }
        } else {
            c.decreaseAllowance(spender, subtractedValue);
            decReverted = false;
        }

        uint256 allowFinal = c.allowance(address(this), spender);

        assert(
            allowAfterIncrease == addedValue &&
            (
                subtractedValue > allowAfterIncrease
                    ? decReverted
                    : (!decReverted && allowFinal == allowAfterIncrease - subtractedValue)
            )
        );
    }

    receive() external payable {}
}

