contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount, uint256 allowanceAmt) public {
        require(recipient != address(0));
        require(amount > 0);
        require(allowanceAmt < type(uint256).max - amount);

        // grant an allowance so transferFrom would be permitted by ERC20 rules
        c.approve(address(this), allowanceAmt);

        bool r1;
        try c.transfer(recipient, amount) { r1 = false; } catch { r1 = true; }

        bool r2;
        try c.transferFrom(address(this), recipient, amount) { r2 = false; } catch { r2 = true; }

        // with no address ever having a transfer role, both transfers must revert
        assert(r1 && r2 && c.balanceOf(recipient) == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 amt1, uint256 amt2) public {
        require(spender != address(0));
        require(amt2 != amt1);

        bool r1;
        try c.approve(spender, amt1) { r1 = false; } catch { r1 = true; }

        uint256 a1 = c.allowance(address(this), spender);

        // second approve with a different value must overwrite the old one
        bool r2;
        try c.approve(spender, amt2) { r2 = false; } catch { r2 = true; }

        assert(!r1 && !r2 && a1 == amt1 && c.allowance(address(this), spender) == amt2);
    }

    receive() external payable {}
}
